import gurobipy as gp
from gurobipy import GRB
tablet_records = [rec for rec in LEGACY_RECORDS if rec['values'].get('Product Name', '').startswith('TABLET_')]
if not tablet_records:
    raise ValueError('No TABLET records found in LEGACY_RECORDS.')
I = []
revenue = {}
inventory = {}
demand = {}
capacity = {}
for rec in tablet_records:
    name = rec['values']['Product Name']
    I.append(name)
    try:
        r = float(rec['values']['Revenue'])
        s = int(rec['values']['Initial Inventory'])
        d = int(rec['values']['Demand'])
    except Exception as e:
        raise ValueError(f'Error parsing record for {name}: {e}')
    revenue[name] = r
    inventory[name] = s
    demand[name] = d
    capacity[name] = min(s, d)
for name in I:
    if name not in revenue or name not in inventory or name not in demand or (name not in capacity):
        raise ValueError(f'Missing data for {name}')
m = gp.Model('Tablet_Fulfillment')
m.Params.MIPGap = 0.0001
x_vars = m.addVars(I, lb=0, ub=[capacity[i] for i in I], vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((revenue[i] * x_vars[i] for i in I)), GRB.MAXIMIZE)
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')